WITH kept_keys AS (SELECT manager_id FROM employees EXCEPT SELECT manager_id FROM employees WHERE UPPER(TRIM(full_name)) = 'JACK TAYLOR'), kept_rows AS (SELECT s.* FROM employees s JOIN kept_keys k ON s.manager_id = k.manager_id) SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, DATE_TRUNC('QUARTER', hire_date) AS quarter_start, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles, GROUPING_ID() AS gid FROM kept_rows GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', hire_date), DATE_TRUNC('QUARTER', hire_date)), (DATE_TRUNC('MONTH', hire_date)), ()) ORDER BY distinct_ids NULLS LAST
